/* Own-account, read-only ledger presentation; server supplies historical balances. */
window.MioCashHistory=(()=>{
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const fmt=v=>{const [a,b='']=String(v??'0').replace(/^-/, '').split('.');return a+'.'+b.padEnd(2,'0').slice(0,Math.max(2,b.replace(/0+$/,'').length))};
 const date=v=>new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Karachi',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v));
 const wallet=v=>v==='exchange'?'Exchange Wallet':'Cash Wallet';
 let api,uid=null,turn=0,page=1,filter='all',rows=[];
 const host=()=>document.getElementById('mioHistory');
 const key=()=>`mio-cash-view:${uid}`;
 function save(){try{sessionStorage.setItem(key(),JSON.stringify({page,filter}))}catch{}}
 function setIdentity(id){if(uid===id)return;turn++;uid=id;rows=[];page=1;filter='all';window.MioTransferReceipt?.clear();host()?.replaceChildren();if(uid){try{const p=JSON.parse(sessionStorage.getItem(key())||'{}');page=Math.max(1,Math.min(100000,Number(p.page)||1));filter=['all','received','sent','package','other'].includes(p.filter)?p.filter:'all'}catch{}}}
 function mount(options){api=options;const target=host();if(!target)return;target.classList.remove('list');const card=target.closest('.card');card?.classList.add('cash-history-card');const heading=card?.querySelector('.card-head');if(heading)heading.innerHTML='<div><h2>Cash Wallet history</h2><p>Received payments, package charges and all Cash Wallet activity. Times: Pakistan.</p></div>';target.addEventListener('change',e=>{if(e.target.matches('[data-cash-filter]')){filter=e.target.value;page=1;save();refresh()}});target.addEventListener('click',e=>{const b=e.target.closest('[data-cash-page],[data-cash-receipt],[data-cash-retry]');if(!b||b.disabled)return;if(b.hasAttribute('data-cash-receipt')){const row=rows.find(x=>x.id===b.dataset.cashReceipt);if(row&&uid)receipt(row);return}if(b.hasAttribute('data-cash-page'))page+=Number(b.dataset.cashPage);save();refresh()})}
 async function refresh(){const target=host();if(!target||!api||!uid)return;const ticket=++turn,owner=uid;target.setAttribute('aria-busy','true');if(!target.children.length)target.innerHTML='<p class="helper" role="status">Updating wallet activity…</p>';try{const {data,error}=await api.rpc('my_cash_wallet_history',{p_filter:filter,p_page:page,p_limit:20});if(ticket!==turn||owner!==uid)return;if(error)throw error;if(!data||!Array.isArray(data.rows))throw Error('Wallet history is unavailable');const pages=Math.max(1,Math.ceil(data.total/20));if(page>pages){page=pages;save();return refresh()}rows=data.rows;render(data)}catch(e){if(ticket===turn&&owner===uid){rows=[];target.innerHTML='<p role="alert">Cash Wallet history could not be refreshed.</p><button class="btn small" data-cash-retry>Retry</button>';api.error?.(e)}}finally{if(ticket===turn)target.removeAttribute('aria-busy')}}
 function label(r){return r.activity_type==='package'?'Self Package '+(r.previous_package_code?'Upgrade':'Activation')+' · '+(r.package_name||r.package_code||'Package'):r.counterparty_name||({'admin_mint':'Company credit','admin_burn':'Company debit'}[r.action])||r.member_name||'Wallet activity'}
 function render(data){const pages=Math.max(1,Math.ceil(data.total/20));host().innerHTML=`<div class="cash-history-tools"><span>${data.total} records · Balance <b>${fmt(data.balance)} MIO</b></span><label>Activity<select data-cash-filter>${[['all','All activity'],['received','Received'],['sent','Sent'],['package','Package charges'],['other','Other activity']].map(([v,t])=>`<option value="${v}" ${filter===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="cash-history-scroll"><table class="cash-history-table"><thead><tr>${['Date & time','Member / Details','Type','Amount','Balance','Reference / note','Status','Receipt'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td>${esc(date(r.created_at))}</td><td><strong>${esc(label(r))}</strong><small>${esc(r.activity_type==='package'?r.member_code:r.counterparty_code||'')}</small></td><td><span class="ex-tag ${Number(r.amount)<0?'sent':''}">${esc(({received:'↓ Received',sent:'↑ Sent',package:'Package charge',other:'Wallet activity'})[r.activity_type])}</span></td><td class="cash-amount ${Number(r.amount)>0?'amount-positive':''}">${Number(r.amount)>0?'+':'−'}${fmt(r.amount)} MIO</td><td class="cash-amount">${Number(r.balance_after)<0?'−':''}${fmt(r.balance_after)} MIO</td><td class="cash-reference">${esc(r.transfer_id||r.activation_id||r.id)}${r.activity_type==='package'?'<small>Package subscription</small>':r.reason?`<small>${esc(r.reason)}</small>`:''}</td><td><span class="ex-tag">Completed</span></td><td><button class="btn small" data-cash-receipt="${esc(r.id)}">View</button></td></tr>`).join(''):'<tr><td colspan="8" class="ex-empty">No wallet activity for this filter.</td></tr>'}</tbody></table></div><div class="ex-pagination"><button class="btn small" data-cash-page="-1" ${page<=1?'disabled':''}>Previous</button><span>${data.total?((page-1)*20+1):0}–${Math.min(page*20,data.total)} of ${data.total} · Page ${page}/${pages}</span><button class="btn small" data-cash-page="1" ${page>=pages?'disabled':''}>Next</button></div>`}
 function receipt(r){const packageCharge=r.activity_type==='package',transfer=['received','sent'].includes(r.activity_type);window.MioTransferReceipt?.show({id:r.transfer_id||r.activation_id||r.id,date:date(r.created_at),amount:fmt(r.amount),heading:packageCharge?'Package Receipt':transfer?'Transfer Receipt':'Wallet Receipt',direction:packageCharge?'Amount charged':Number(r.amount)>0?'Amount received':'Amount sent',sender:{name:r.sender_name,code:r.sender_code},receiver:{name:r.receiver_name,code:r.receiver_code},source:wallet(r.source_wallet),destination:wallet(r.destination_wallet),note:r.reason||'',details:packageCharge?[['Activity',r.previous_package_code?'Self Package Upgradation':'Self Package Activation'],['Member',r.member_name],['MIO ID',r.member_code],['Package',(r.previous_package_name||r.previous_package_code||'Free')+' → '+(r.package_name||r.package_code||'Package')],['Paid from','Cash Wallet'],['Purpose','Package subscription'],['Balance before',fmt(r.balance_before)+' MIO'],['Balance after',fmt(r.balance_after)+' MIO']]:!transfer?[['Member',r.member_name],['MIO ID',r.member_code],['Activity',String(r.action).replaceAll('_',' ')],['Wallet','Cash Wallet'],['Balance before',fmt(r.balance_before)+' MIO'],['Balance after',fmt(r.balance_after)+' MIO']]:null})}
 return {mount,setIdentity,refresh};
})();
